// 处理中文RSS新闻源
const allArticles = [];

// 中文交易相关关键词
const chineseKeywords = [
  '股票', '股市', '证券', '基金', '期货', '外汇', '投资', '交易',
  'A股', '港股', '沪深', '上证', '深证', '创业板', '科创板',
  '央行', '货币政策', '利率', '准备金率', 'GDP', 'CPI', 'PPI', 'PMI',
  '涨跌', '涨停', '跌停', '买入', '卖出', '开盘', '收盘',
  '财报', '业绩', '营收', '利润', '亏损', '股价', '汇率',
  '房地产', '新能源', '芯片', '医药', '白酒', '银行', '保险',
  '原油', '黄金', '白银', '铜', '大豆', '玉米', '中美', '贸易'
];

// 英文关键词
const englishKeywords = [
  'stock', 'market', 'trading', 'investment', 'earnings', 'revenue',
  'fed', 'federal reserve', 'inflation', 'gdp', 'economy', 'nasdaq', 
  'dow', 'sp500', 's&p', 'yuan', 'rmb', 'pboc'
];

const allKeywords = [...chineseKeywords, ...englishKeywords];

// 处理每个RSS源的响应
for (const item of $input.all()) {
  try {
    const xmlData = item.json.data || item.json;

    // 解析RSS XML - 支持中文内容
    const parser = require('xml2js');

    // 简单的正则解析方式
    const itemPattern = /<item[^>]*>([\s\S]*?)<\/item>/g;
    const items = xmlData.match(itemPattern) || [];

    for (let i = 0; i < Math.min(items.length, 20); i++) {
      const itemXml = items[i];

      // 提取标题
      const titleMatch = itemXml.match(/<title[^>]*><!\[CDATA\[([^\]]+)\]\]><\/title>|<title[^>]*>([^<]+)<\/title>/);
      const title = titleMatch ? (titleMatch[1] || titleMatch[2] || '').trim() : '';

      // 提取链接
      const linkMatch = itemXml.match(/<link[^>]*><!\[CDATA\[([^\]]+)\]\]><\/link>|<link[^>]*>([^<]+)<\/link>/);
      const link = linkMatch ? (linkMatch[1] || linkMatch[2] || '').trim() : '';

      // 提取描述
      const descMatch = itemXml.match(/<description[^>]*><!\[CDATA\[([^\]]+)\]\]><\/description>|<description[^>]*>([^<]+)<\/description>/);
      const description = descMatch ? (descMatch[1] || descMatch[2] || '').replace(/<[^>]+>/g, '').trim() : '';

      // 提取发布时间
      const dateMatch = itemXml.match(/<pubDate[^>]*>([^<]+)<\/pubDate>/);
      const pubDate = dateMatch ? dateMatch[1].trim() : '';

      if (title && link && title.length > 5) {
        // 检查是否包含交易相关关键词
        const content = title + ' ' + description;
        const isRelevant = allKeywords.some(keyword => {
          return content.toLowerCase().includes(keyword.toLowerCase()) ||
                 content.includes(keyword);
        });

        if (isRelevant) {
          // 计算置信度评分
          let relevanceScore = 0;
          let keywordMatches = 0;

          for (const keyword of allKeywords) {
            if (content.toLowerCase().includes(keyword.toLowerCase()) || content.includes(keyword)) {
              keywordMatches++;
              // 中文关键词权重更高
              relevanceScore += chineseKeywords.includes(keyword) ? 1.5 : 1.0;
            }
          }

          // 标题匹配加分
          if (allKeywords.some(k => title.toLowerCase().includes(k.toLowerCase()) || title.includes(k))) {
            relevanceScore += 2;
          }

          // 规范化评分到0-10
          relevanceScore = Math.min(10, Math.max(1, relevanceScore));

          allArticles.push({
            title: title,
            url: link,
            summary: description,
            published_at: pubDate,
            source: item.json.url || 'Chinese RSS Feed',
            relevance_score: relevanceScore,
            keyword_matches: keywordMatches,
            language: 'zh-CN',
            extracted_at: new Date().toISOString()
          });
        }
      }
    }
  } catch (error) {
    console.log('Error parsing Chinese RSS:', error.message);
  }
}

// 去重处理 - 基于URL和标题相似度
const uniqueArticles = [];
const seenUrls = new Set();
const seenTitles = new Set();

for (const article of allArticles) {
  // URL去重
  if (seenUrls.has(article.url)) continue;

  // 标题相似度去重（简单版本）
  let isDuplicate = false;
  for (const seenTitle of seenTitles) {
    if (article.title.length > 10 && seenTitle.length > 10) {
      // 检查标题相似度
      const similarity = article.title.length > seenTitle.length ? 
        seenTitle.length / article.title.length : 
        article.title.length / seenTitle.length;

      if (similarity > 0.8 && (article.title.includes(seenTitle.substring(0, 10)) || seenTitle.includes(article.title.substring(0, 10)))) {
        isDuplicate = true;
        break;
      }
    }
  }

  if (!isDuplicate) {
    seenUrls.add(article.url);
    seenTitles.add(article.title);
    uniqueArticles.push(article);
  }
}

// 按相关性评分排序
uniqueArticles.sort((a, b) => b.relevance_score - a.relevance_score);

console.log(`Processed ${uniqueArticles.length} unique Chinese articles`);

return uniqueArticles.map(article => ({ json: article }));
